const installArtifact=ref<any>(null),clientEditingId=ref<string|null>(null),inboundEditingId=ref<string|null>(null),adminEditingId=ref<string|null>(null),adminSearch=ref(""),adminRoleFilter=ref(""),adminStatusFilter=ref(""),adminPage=ref(1),adminPageSize=4;
const visibleSections=computed(()=>{if(me.value?.role==="representative")return sections.filter(x=>x[0]==="clients");if(me.value?.role==="tenant_operator")return sections.filter(x=>!["admins","settings"].includes(x[0]));return sections});
const allowedClientInbounds=computed(()=>me.value?.role==="representative"?adminInboundRows.value:inboundRows.value);
