 const q=adminSearch.value.trim().toLowerCase();
 return adminRows.value.filter(a=>!["platform_owner","tenant_manager"].includes(a.role)).filter(a=>{
  const text=[a.email,a.role,adminRoleLabel(a.role)].join(" ").toLowerCase();
