const formatBytes=(n:number)=>{if(!n)return "0 B";const u=["B","KB","MB","GB","TB","PB"];const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return (n/Math.pow(1024,i)).toFixed(i?2:0)+" "+u[i]};
const trafficTotalLabel=computed(()=>formatBytes(trafficTotal.value));
const trafficInLabel=computed(()=>formatBytes(trafficIn.value));
const trafficOutLabel=computed(()=>formatBytes(trafficOut.value));
const filteredTrafficRows=computed(()=>trafficBreakdown.value.filter(x=>{const q=trafficSearch.value.trim().toLowerCase();return(!q||[x.client_name,x.client_id,x.node_id,x.inbound_id,x.protocol].join(" ").toLowerCase().includes(q))}));
const filteredAuditRows=computed(()=>{const q=auditSearch.value.trim().toLowerCase();const since=Date.now()-auditDays.value*86400000;return auditRows.value.filter(x=>{const text=[x.action,x.resource,x.resource_id,x.actor_email,x.ip,x.request_id].join(" ").toLowerCase();const ts=x.created_at?new Date(x.created_at).getTime():0;return(!q||text.includes(q))&&(!auditActionFilter.value||x.action===auditActionFilter.value)&&(!auditResultFilter.value||String(x.result).toLowerCase()===auditResultFilter.value.toLowerCase())&&(!ts||ts>=since)})});
